    48|// ── Twilio ─────────────────────────────────────────────────
    49|
    50|async function sendTwilioSms(
    51|  phone: string,
    52|  body: string,
    53|  accountSid: string,
    54|  authToken: string,
    55|): Promise<{ ok: boolean; sid?: string; error?: string }> {
    56|  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
    57|  const encoded = btoa(`${accountSid}:${authToken}`);
    58|
    59|  const form = new URLSearchParams();
    60|  form.append("To", phone);
    61|  form.append("Body", body);
    62|  (Deno.env.get("TWILIO_MESSAGING_SERVICE_SID") || Deno.env.get("TWILIO_FROM_NUMBER"))?.let((v) =>
    63|    form.append(Deno.env.get("TWILIO_MESSAGING_SERVICE_SID") ? "MessagingServiceSid" : "From", v),
    64|  );
    65|
    66|  const resp = await fetch(url, {
    67|    method: "POST",
    68|    headers: { Authorization: `Basic ${encoded}`, "Content-Type": "application/x-www-form-urlencoded" },
    69|    body: form.toString(),
    70|  });
    71|  const data = await resp.json();
    72|  if (!resp.ok) {
    73|    console.error("Twilio error:", data);
    74|    return { ok: false, error: data.message || "SMS send failed" };
    75|  }
    76|  return { ok: true, sid: data.sid };
    77|}
    78|
    79|// ── Supabase clients ───────────────────────────────────────
    80|
    81|function adminClient() {
    82|  return createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    83|}
    84|
    85|function anonClient() {
    86|  return createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_ANON_KEY")!);
    87|}
    88|
    89|// ── Helpers ────────────────────────────────────────────────
    90|
    91|function norm(phone: string): string {
    92|  let p = phone.replace(/\s+/g, "").trim();
    93|  if (!p.startsWith("+")) p = "+" + p;
    94|  return p;
    95|}
    96|
    97|// ── Main ───────────────────────────────────────────────────
    98|
    99|Deno.serve(async (req: Request) => {
   100|  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
   101|
   102|  try {
   103|    const p = await req.json();
   104|    const action = p.action as string;
   105|
   106|    if (action === "send_otp") return await handleSendOtp(req, p);
   107|    if (action === "verify_otp") return await handleVerifyOtp(req, p);
   108|    if (action === "set_config") return await handleSetConfig(req, p);
   109|    // Legacy hook mode: GoTrue calls us with { phone, otp }
   110|    if (p.phone && p.otp) return await handleSendOtp(req, { ...p, action: "send_otp" });
   111|
   112|    return new Response(JSON.stringify({ error: "Use { action: 'send_otp' | 'verify_otp' }" }), {
   113|      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   114|    });
   115|  } catch (err) {
   116|    console.error("send-sms error:", err);
   117|    return new Response(JSON.stringify({ error: "Internal server error" }), {
   118|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   119|    });
   120|  }
   121|});
   122|
   123|// ── send_otp ───────────────────────────────────────────────
   124|
   125|async function handleSendOtp(req: Request, payload: Record<string, unknown>) {
   126|  const phone = norm((payload.phone as string) || "");
   127|  if (!phone || phone.length < 10) {
   128|    return new Response(JSON.stringify({ error: "Valid phone number required" }), {
   129|      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   130|    });
   131|  }
   132|
   133|  // Try: Deno.env → database → headers
   134|  let sid = "";
   135|  let tok = "";
   136|
   137|  // 1. Deno env vars (production best practice)
   138|  sid = Deno.env.get("TWILIO_ACCOUNT_SID") || "";
   139|  tok = Deno.env.get("TWILIO_AUTH_TOKEN") || "";
   140|
   141|  // 2. Database config table (auto-provisioned fallback)
   142|  if (!sid || !tok) {
   143|    const { data: cfg } = await adminClient().from("app_config").select("key,value").in("key", ["twilio_sid","twilio_token"]);
   144|    if (cfg) {
   145|      sid = cfg.find((r: {key:string,value:string}) => r.key === "twilio_sid")?.value || "";
   146|      tok = cfg.find((r: {key:string,value:string}) => r.key === "twilio_token")?.value || "";
   147|    }
   148|  }
   149|
   150|  // 3. Request headers (least secure, development only)
   151|  if (!sid || !tok) {
   152|    sid = req.headers.get("x-twilio-account-sid") || "";
   153|    tok = req.headers.get("x-twilio-auth-token") || "";
   154|  }
   155|  if (!sid || !tok) {
   156|    return new Response(JSON.stringify({ error: "SMS provider not configured. Set TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN in Supabase Dashboard > Edge Functions > Secrets." }), {
   157|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   158|    });
   159|  }
   160|
   161|  const otp = (payload.otp as string) || generateOtp();
   162|  const salt = crypto.randomUUID();
   163|  const hash = await sha256(`${phone}:${otp}:${salt}`);
   164|
   165|  const { error: dbErr } = await adminClient().from("phone_otps").insert({
   166|    phone, otp_hash: hash, salt,
   167|    expires_at: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
   168|  });
   169|  if (dbErr) {
   170|    console.error("OTP store error:", dbErr);
   171|    return new Response(JSON.stringify({ error: "Failed to generate OTP" }), {
   172|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   173|    });
   174|  }
   175|
   176|  const res = await sendTwilioSms(phone, `Your VitaHero verification code is: ${otp}`, sid, tok);
   177|  if (!res.ok) {
   178|    return new Response(JSON.stringify({ error: res.error }), {
   179|      status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" },
   180|    });
   181|  }
   182|
   183|  return new Response(JSON.stringify({ success: true, expiresIn: 300 }), {
   184|    headers: { ...corsHeaders, "Content-Type": "application/json" },
   185|  });
   186|}
   187|
   188|// ── verify_otp ─────────────────────────────────────────────
   189|
   190|async function handleVerifyOtp(req: Request, payload: Record<string, unknown>) {
   191|  const phone = norm((payload.phone as string) || "");
   192|  const otp = (payload.otp as string) || "";
   193|  if (!phone || otp.length !== 6) {
   194|    return new Response(JSON.stringify({ error: "Phone and 6-digit OTP required" }), {
   195|      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   196|    });
   197|  }
   198|
   199|  const admin = adminClient();
   200|
   201|  // Look up unverified, non-expired OTPs
   202|  const { data: records, error: lookErr } = await admin
   203|    .from("phone_otps")
   204|    .select("*")
   205|    .eq("phone", phone)
   206|    .eq("verified", false)
   207|    .gt("expires_at", new Date().toISOString())
   208|    .order("created_at", { ascending: false })
   209|    .limit(5);
   210|
   211|  if (lookErr || !records?.length) {
   212|    return new Response(JSON.stringify({ error: "No active OTP found. Request a new code." }), {
   213|      status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
   214|    });
   215|  }
   216|
   217|  // Match OTP against salted hashes
   218|  let matched: (typeof records)[0] | null = null;
   219|  for (const r of records) {
   220|    if ((await sha256(`${phone}:${otp}:${r.salt || ""}`)) === r.otp_hash) {
   221|      matched = r;
   222|      break;
   223|    }
   224|  }
   225|  if (!matched) {
   226|    return new Response(JSON.stringify({ error: "Invalid OTP. Please try again." }), {
   227|      status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
   228|    });
   229|  }
   230|
   231|  // Mark verified
   232|  await admin.from("phone_otps").update({ verified: true }).eq("id", matched.id);
   233|
   234|  // ── User provisioning ──────────────────────────────────
   235|  // Find existing user or create a new one
   236|  let userId: string | null = null;
   237|  const { data: users } = await admin.auth.admin.listUsers();
   238|  const existing = users?.users?.find((u) => u.phone === phone);
   239|  if (existing) {
   240|    userId = existing.id;
   241|  }
   242|
   243|  const password = generatePassword();
   244|
   245|  if (userId) {
   246|    // Update existing user's password so we can sign them in
   247|    await admin.auth.admin.updateUserById(userId, { password });
   248|  } else {
   249|    // Create new user with phone identity + password
   250|    const { data: newUser, error: createErr } = await admin.auth.admin.createUser({
   251|      phone,
   252|      password,
   253|      phone_confirm: true,
   254|      user_metadata: { name: "Parent", signup_method: "phone" },
   255|    });
   256|    if (createErr || !newUser?.user) {
   257|      console.error("User creation failed:", createErr);
   258|      return new Response(JSON.stringify({ error: "Failed to create account" }), {
   259|        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   260|      });
   261|    }
   262|    userId = newUser.user.id;
   263|  }
   264|
   265|  // ── Sign in to get session tokens ──────────────────────
   266|  const { data: session, error: signInErr } = await anonClient().auth.signInWithPassword({
   267|    phone,
   268|    password,
   269|  });
   270|
   271|  if (signInErr || !session?.session) {
   272|    console.error("Sign-in failed:", signInErr);
   273|    // Fallback: return just the user_id so the Android app can proceed
   274|    return new Response(JSON.stringify({
   275|      success: true,
   276|      user_id: userId,
   277|      phone,
   278|      note: "User created. Session not available — retry verification.",
   279|    }), {
   280|      headers: { ...corsHeaders, "Content-Type": "application/json" },
   281|    });
   282|  }
   283|
   284|  return new Response(JSON.stringify({
   285|    success: true,
   286|    user_id: userId,
   287|    phone,
   288|    access_token: session.session.access_token,
   289|    refresh_token: session.session.refresh_token,
   290|    user: session.user ? {
   291|      id: session.user.id,
   292|      email: session.user.email,
   293|      phone: session.user.phone,
   294|    } : null,
   295|  }), {
   296|    headers: { ...corsHeaders, "Content-Type": "application/json" },
   297|  });
   298|}
   299|
   300|// ── set_config (bootstrap Twilio creds from database) ─────
   301|
   302|async function handleSetConfig(req: Request, payload: Record<string, unknown>) {
   303|  const key = (payload.key as string) || "";
   304|  const value = (payload.value as string) || "";
   305|  const secret = (payload.secret as string) || "";
   306|
   307|  // Simple shared secret to prevent unauthorised config writes
   308|  const expectedSecret = Deno.env.get("CONFIG_SECRET") || "vitahero-bootstrap-2026";
   309|  if (secret !== expectedSecret) {
   310|    return new Response(JSON.stringify({ error: "Unauthorised" }), {
   311|      status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
   312|    });
   313|  }
   314|
   315|  if (!key || !value) {
   316|    return new Response(JSON.stringify({ error: "key and value required" }), {
   317|      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   318|    });
   319|  }
   320|
   321|  // Ensure app_config table exists
   322|  await adminClient().rpc("exec_sql", {
   323|    sql: "CREATE TABLE IF NOT EXISTS app_config (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TIMESTAMPTZ DEFAULT now())"
   324|  }).maybeSingle();
   325|
   326|  const { error } = await adminClient().from("app_config").upsert({
   327|    key, value, updated_at: new Date().toISOString(),
   328|  });
   329|
   330|  if (error) {
   331|    return new Response(JSON.stringify({ error: "Failed to save config" }), {
   332|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   333|    });
   334|  }
   335|
   336|  return new Response(JSON.stringify({ success: true, key }), {
   337|    headers: { ...corsHeaders, "Content-Type": "application/json" },
   338|  });
