    18|/**
    19| * Bridges the Android app to Supabase Postgres via the REST API.
    20| * Uses the user's access token when authenticated, falls back to anon key.
    21| */
    22|class SupabaseRepository {
    23|
    24|    private val http get() = SupabaseService.http
    25|    private val base get() = "${SupabaseService.baseUrl}/rest/v1"
    26|    private val anonKey get() = SupabaseService.anonKey
    27|
    28|    /**
    29|     * Current access token, set by AppViewModel after successful auth.
    30|     * When null, falls back to the anon key for unauthenticated access.
    31|     */
    32|    var accessToken: String? = null
    33|
    34|    /** Returns authenticated headers. When logged in, includes Bearer token for RLS. */
    35|    private fun authHeaders(): Map<String, String> {
    36|        val headers = mutableMapOf(
    37|            "apikey" to anonKey,
    38|            "Content-Type" to "application/json"
    39|        )
    40|        accessToken?.let { headers["Authorization"] = "Bearer $it" }
    41|        return headers
    42|    }
    43|
    44|    // ─── Profiles ──────────────────────────────────────────────
    45|
    46|    suspend fun upsertProfile(dto: ProfileDto) = onIo {
    47|        val headers = authHeaders()
    48|        http.post("$base/profiles") {
    49|            headers.forEach { (k, v) -> header(k, v) }
    50|            header("Prefer", "resolution=merge-duplicates")
    51|            contentType(ContentType.Application.Json)
    52|            setBody(dto)
    53|        }
    54|    }
    55|
    56|    suspend fun fetchProfile(profileId: String): ProfileDto? = onIo {
    57|        val headers = authHeaders()
    58|        val resp = http.get("$base/profiles") {
    59|            headers.forEach { (k, v) -> header(k, v) }
    60|            header("Prefer", "return=representation")
    61|            url { parameters.append("id", "eq.$profileId") }
    62|        }
    63|        if (resp.status.isSuccess()) resp.body<List<ProfileDto>>().firstOrNull() else null
    64|    }
    65|
