     9|/**
    10| * Offline-first sync queue for Supabase operations.
    11| *
    12| * When the network is unavailable, mutations are queued here and
    13| * retried automatically once connectivity is restored. Each entry
    14| * stores the operation parameters so it can be replayed.
    15| *
    16| * In production, replace with WorkManager for guaranteed execution
    17| * across process death. For now this provides same-session durability.
    18| */
    19|object SyncQueue {
    20|
    21|    private val pendingOps = ConcurrentLinkedQueue<SyncOp>()
    22|
    23|    data class SyncOp(
    24|        val type: SyncType,
    25|        val payload: String, // JSON serialized DTO
    26|        val retries: Int = 0,
    27|        val createdAt: Long = System.currentTimeMillis()
    28|    )
    29|
    30|    enum class SyncType {
    31|        UPSERT_PROFILE,
    32|        UPSERT_KIDS,
    33|        UPSERT_APPOINTMENT,
    34|        UPSERT_MEAL,
    35|        UPSERT_STREAK,
    36|        UPSERT_GROWTH_POINT,
    37|        UPSERT_COPARENT,
    38|    }
    39|
    40|    private const val MAX_RETRIES = 5
    41|    private const val BASE_DELAY_MS = 2_000L
    42|
    43|    fun enqueue(type: SyncType, payload: String) {
    44|        pendingOps.add(SyncOp(type, payload))
    45|    }
    46|
    47|    fun pendingCount(): Int = pendingOps.size
    48|
    49|    /**
    50|     * Process all pending sync operations.
    51|     * Call this when connectivity is restored or after auth.
    52|     */
    53|    suspend fun processAll(repository: SupabaseRepository, context: Context) {
    54|        val toRetry = mutableListOf<SyncOp>()
    55|        while (true) {
    56|            val op = pendingOps.poll() ?: break
    57|            try {
    58|                executeOp(op, repository, context)
    59|            } catch (e: Exception) {
    60|                if (op.retries < MAX_RETRIES) {
    61|                    toRetry.add(op.copy(retries = op.retries + 1))
    62|                }
    63|            }
    64|        }
    65|        // Re-enqueue failed ops for later retry
    66|        toRetry.forEach { pendingOps.add(it) }
    67|    }
    68|
    69|    private suspend fun executeOp(op: SyncOp, repository: SupabaseRepository, context: Context) {
    70|        // Delay between retries with exponential backoff
    71|        if (op.retries > 0) {
    72|            kotlinx.coroutines.delay(BASE_DELAY_MS * (1L shl (op.retries - 1).coerceAtMost(4)))
    73|        }
    74|        // Parse and execute based on type
    75|        val json = kotlinx.serialization.json.Json { ignoreUnknownKeys = true; isLenient = true }
    76|        when (op.type) {
    77|            SyncType.UPSERT_PROFILE -> {
    78|                val dto = json.decodeFromString<ProfileDto>(op.payload)
    79|                repository.upsertProfile(dto)
    80|            }
    81|            SyncType.UPSERT_KIDS -> {
    82|                val dtos = json.decodeFromString<List<KidDto>>(op.payload)
    83|                repository.upsertKids(dtos)
    84|            }
    85|            SyncType.UPSERT_APPOINTMENT -> {
    86|                val dto = json.decodeFromString<AppointmentDto>(op.payload)
